CREATE TABLE IF NOT EXISTS gis_spatial_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_id uuid NOT NULL REFERENCES gis_layers(id) ON DELETE CASCADE, external_feature_id text, feature_type text, properties jsonb NOT NULL DEFAULT '{}'::jsonb, geometry_json jsonb, geometry_status text NOT NULL DEFAULT 'Unverified', source_timestamp timestamptz, ingested_at timestamptz NOT NULL DEFAULT now(), UNIQUE(layer_id,external_feature_id));
CREATE TABLE IF NOT EXISTS gis_spatial_analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, analysis_type text NOT NULL, target_layer_id uuid REFERENCES gis_layers(id) ON DELETE SET NULL, result_status text NOT NULL DEFAULT 'Pending', result_summary text, findings jsonb NOT NULL DEFAULT '{}'::jsonb, confidence_score numeric(6,2), source_references jsonb NOT NULL DEFAULT '[]'::jsonb, performed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_connector_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES gis_data_sources(id) ON DELETE CASCADE, connector_type text NOT NULL, endpoint text, run_status text NOT NULL DEFAULT 'Queued', started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, records_seen integer NOT NULL DEFAULT 0, records_normalized integer NOT NULL DEFAULT 0, records_rejected integer NOT NULL DEFAULT 0, error_summary text, provenance_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS idx_spatial_features_layer ON gis_spatial_features(layer_id,geometry_status);
CREATE INDEX IF NOT EXISTS idx_spatial_analyses_asset ON gis_spatial_analyses(asset_id,performed_at DESC);
CREATE INDEX IF NOT EXISTS idx_connector_runs_source ON gis_connector_runs(source_id,started_at DESC);